/*---
description: az locale lowercase maps every code point U+060000-U+06ffff
features: [ts-unicode-locale-case, ts-unicode-exhaustive, ts-strings, ts-arrays, ts-numbers]
---*/
// Generated by tooling/unicode-cases/locale-case.ts; expected values are from Node.
// Oracle: Node 24.20.0; Unicode 17.0; ICU 78.3.
// docs/foundations/unicode.md: locale-sensitive casing and Staying identical to node.
// Hash each 4096-code-point block independently, including lone surrogate
// code units in the BMP. Fold every output UTF-16 code unit with FNV-1a.
const expected: number[] = [0x36bf21c5, 0xe87621c5, 0x49ce09c5, 0x6ef829c5, 0x12be89c5, 0x615ec9c5, 0x0339b1c5, 0x86baa1c5, 0x013459c5, 0xb60521c5, 0x91ae69c5, 0x4bd029c5, 0x27ccf1c5, 0x5f2769c5, 0x235159c5, 0x0b48f9c5];
const start = 0x060000;
for (let block = 0; block < expected.length; block++) {
  const first = start + block * 0x1000;
  let hash = 0x811c9dc5;
  for (let codePoint = first; codePoint < first + 0x1000; codePoint++) {
    const result = String.fromCodePoint(codePoint).toLocaleLowerCase("\u0061\u007a");
    for (let index = 0; index < result.length; index++) {
      hash = Math.imul(hash ^ result.charCodeAt(index), 0x01000193) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], "\u0061\u007a\u0020\u006c\u006f\u0077\u0065\u0072\u0020\u0055\u002b" + first.toString(16) + "\u002d\u0055\u002b" + (first + 0xfff).toString(16));
}
